import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"5.3 总结并评估可复用方法","description":"新方法先做候选，经过评估和小范围试用后才能采用。","frontmatter":{"title":"5.3 总结并评估可复用方法","description":"新方法先做候选，经过评估和小范围试用后才能采用。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5/5-3.md","filePath":"delivery/stage-5/5-3.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-5/5-3.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_5-3-总结并评估可复用方法" tabindex="-1">5.3 总结并评估可复用方法 <a class="header-anchor" href="#_5-3-总结并评估可复用方法" aria-label="Permalink to &quot;5.3 总结并评估可复用方法&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 从成功任务中总结可复用的方法，但新方法只能作为候选，必须经过评估和小范围试用后才能成为正式能力。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>从多次成功的真实任务中提取共同步骤，形成带适用范围和示例的候选方法。</li><li>为候选方法准备成功样本、失败样本和对照结果，避免只挑好看的数据。</li><li>先在不产生真实影响的情况下试运行，再在小范围真实任务中试用。</li><li>试用期间比较成功率、人工时间、成本和失败类型，用户能看懂差异。</li><li>新方法不能自动扩大权限，涉及高风险动作时仍然需要审批。</li><li>保留旧版本，出现问题时可以立即退回。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
